"""Build the public report from measured, authored-stimulus results only."""
import json,html,statistics,shutil
from pathlib import Path
ROOT=Path(__file__).parent
r=json.loads((ROOT/'benchmark-result.json').read_text());browser=json.loads((ROOT/'tests/browser-result.json').read_text())
def esc(x):return html.escape(str(x))
def table(headers,rows):return '<div style="overflow:auto"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def median(xs):return statistics.median(xs)
def sec(ms):return f'{ms/1000:.3f} s'
base=[[x['audio_s'],x['classes'],sec(x['inference_ms']),x['reuse']['audio_encoder_calls'],x['reuse']['audio_feature_cache_hits']] for x in r['rows'] if x['label']=='baseline']
groups=[[x['method'],x['group_size'],sec(x['inference_ms'])] for x in r['rows'] if x['label']=='group_comparison']
hops=[]
for hop in [100,200,300]:
 times=lambda repeat:[x['inference_ms'] for x in r['rows'] if x['label']=='optimized_hops' and x['hop_ms']==hop and x['repeat_target']==repeat]
 a,b=times(False),times(True);hops.append([f'{hop} ms',sec(median(a)),f'{sec(min(a))} – {sec(max(a))}',sec(median(b)),f'{median(a)/hop:.1f}× hop budget'])
live=[]
for x in browser['live']:
 good=[v for v in x['rows'] if v['inference_ms'] is not None];missing=sum(v['status']!='evaluated' for v in x['rows'])
 live.append([16,str(x['hop_ms'])+' ms',len(good),sec(median(v['inference_ms'] for v in good)),sec(median(x['ages'])),sec(max(x['ages'])),f'{missing}/{len(x["rows"])} ({missing/len(x["rows"]):.0%})'])
full_path=ROOT/'tests/full-live-result.json'
if full_path.exists():
 full=json.loads(full_path.read_text());runs=full.get('runs',[full])
 for x in runs:
  good=[v for v in x['rows'] if v['inference_ms'] is not None];missing=sum(v['status']!='evaluated' for v in x['rows'])
  live.append([527,str(x['settings']['hop_ms'])+' ms',len(good),sec(median(v['inference_ms'] for v in good)),sec(median(x['ages'])),sec(max(x['ages'])),f'{missing}/{len(x["rows"])} ({missing/len(x["rows"]):.0%})'])
focus=[]
for x in r['rows']:
 if x['label']=='focus_probe':focus.append([x['signal'],'yes' if x['repeat_target'] else 'no',f'{x["scores"]["/m/02fs_r"]:.3f}',f'{x["scores"]["/m/028v0c"]:.3f}'])
reuse=[x for x in r['rows'] if x['label']=='reuse_equivalence'];warm=next(x for x in r['rows'] if x['label']=='warmup')
checks=browser['checks'][:]
p=ROOT/'tests/api-result.json'
if p.exists():checks+=json.loads(p.read_text())['checks']
p=ROOT/'tests/optional-lab-result.json';optional='The optional-lab compatibility check has not completed.'
if p.exists():
 av=json.loads(p.read_text());optional=f"Existing MOSS Audio + LFM3-VL lab returned HTTP {av['av_status']} after idle d1 unloading; cold load and a three-second fixture analysis took {av['av_elapsed_s']:.1f} s. Robby ready afterwards: {av['robby_ready']}."
body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audio Decision · measured results</title><link rel="stylesheet" href="./style.css"><style>main{{max-width:1120px}}h1{{font-size:44px}}h2{{font-size:22px;letter-spacing:-.4px;color:var(--ink);margin:24px 0 15px}}p,li{{line-height:1.7}}table{{width:100%;border-collapse:collapse;font-size:13px;margin:16px 0}}td,th{{text-align:left;padding:11px;border-bottom:1px solid var(--line)}}th{{background:#e9f1e5}}code{{font-size:12px;overflow-wrap:anywhere}}.caution{{border-left:4px solid #c77525;background:#fff2df;padding:16px 22px;border-radius:8px}}.report-intro{{padding:40px 0 20px}}</style></head><body><header><a class="brand" href="./">ROBBY <span>RESEARCH</span></a><a href="./">Open Audio Decision Lab ↗</a></header><main><div class="report-intro"><p class="eyebrow">MEASURED ON 8 NOVEMBER 2026</p><h1>Faster decisions.<br><em>Honest temporal limits.</em></h1><p>Local LiquidAI d1-Omni-2B on a shared RTX 3090. Every score below comes from actual model inference. The browser tests traverse the existing public Cloudflare tunnel.</p></div>
<section class="panel"><h2>The useful conclusion</h2><p>All 527 classes take about <strong>2.3–2.5 seconds per window</strong> in the fastest tested stable configuration: BF16, multi-label choice, 64 classes per group, with shared audio features. Binary groups of 16 take about 7.3 seconds for a ten-second history. Neither sustains all classes every 100–300 ms. A selected 16-class live view is much more responsive.</p><div class="caution"><strong>Temporal focus is not reliable enough to call this a validated SED system.</strong> An early beep was still reported in the final, silent interval. Repeating the target audio did not solve this. The page exposes the failure rather than replacing the model with fake probabilities or a different classifier.</div></section>
<section class="panel"><h2>Full-class speed: 100, 200 and 300 ms grids</h2><p>527 classes, 10 seconds of audio history, multi-label groups of 64, three warm repetitions per cell. Median and range are wall-clock inference times with CUDA synchronization. Other GPU jobs were present. The hop changes the requested interval, not the amount of history recomputed.</p>{table(['Target interval','History only · median','History only · range','History + target · median','Compute / hop'],hops)}<p>Repeating a 100–300 ms target increases measured median time modestly here. It is a real second audio item, not a fabricated API. No statistically established quality benefit is claimed.</p></section>
<section class="panel"><h2>Actual live capture → rendered result</h2><p>Chrome headless, authored WAV fed through the browser microphone, AudioWorklet resampling, public HTTPS/WebSocket, actual GPU processing, and the next UI rendering frame. Multi-label groups of 64. Latency is measured from the target interval’s browser capture timestamp, including transport and buffering. These are short smoke tests, not service-level latency guarantees. Microphone hardware/driver latency is not independently measured.</p>{table(['Classes','Grid','Results','GPU median','End-to-end median','End-to-end max','Missing intervals'],live)}<p>The scheduler finishes one inference and selects the newest complete interval. It records skipped grid cells as null. It does not hold old values forward or fill missing classes with zero. Drop counts include the final incomplete/unscored tail. Each live test preserves its recording for later playback.</p></section>
<section class="panel"><h2>History length and class count</h2><p>Documented baseline: independent binary <code>noul</code> questions, groups of 16, 200 ms target, no repeated target, one warm measurement per configuration. A larger dedicated-device study would be needed for confidence intervals.</p>{table(['History (s)','Classes','Inference','Audio encoder calls','Feature reuses'],base)}<p>For 527 questions there are 33 group forwards, not one magic forward pass. Each group still processes the model context. The audio encoder is called only once per window; its exact same input features are reused across groups.</p><h2>Question grouping ablation</h2><p>100 classes, five-second history, one warm measurement per cell. Multi-label scores are independent, never normalized to sum to one. Group size and wording can affect values; these are speed comparisons, not accuracy equivalence tests.</p>{table(['Question formulation','Classes / group','Inference'],groups)}</section>
<section class="panel"><h2>Optimization, startup and memory</h2><ul><li>Model load: {sec(r['load_ms'])}. First inference / kernel warm-up: {sec(warm['inference_ms'])}, shown separately from warm times.</li><li>Reusing audio preprocessing and projected features reduced the 100-class binary comparison from {sec(reuse[0]['inference_ms'])} to {sec(reuse[1]['inference_ms'])}. Maximum absolute score difference: {r['reuse_max_abs_score_difference']}.</li><li>About {max(x['allocated_mb'] for x in r['rows']):.0f} MiB PyTorch allocation and {max(x['reserved_mb'] for x in r['rows']):.0f} MiB reserved in these tests; CUDA context overhead is additional. Loading requires at least 6 GiB free. The model remains loaded until the optional AV lab needs its slot.</li><li>Official <code>model.compile()</code> was tested and failed with <code>InternalTorchDynamoError</code> on this Torch 2.6 installation. It is not enabled. No shared CUDA or Torch upgrade was performed.</li><li>Language-model KV reuse across question groups is not assumed safe: the official decision-set forward uses joint bidirectional processing. Audio features alone are cached within a window.</li></ul><p>{esc(optional)}</p></section>
<section class="panel"><h2>Temporal-focus counterexample</h2><p>Authored two-second recording, 880 Hz beep at amplitude 0.2 for 200 ms, either at the start or end, or no beep. Target: final 200 ms. Binary questions, fixed misleading swimming-pool scene context, five classes. This is a small diagnostic, not an AudioSet accuracy estimate.</p>{table(['Signal','Separate target repeat','Beep score','Silence score'],focus)}<p>“Early” means the target is silent. A higher beep score there than for “late” is a failure of time localization. Silence also receives nonzero sound scores. Raw exports preserve this evidence. A realistic next evaluation would use labeled onset/offset recordings, counterfactual contexts, multiple durations and per-class calibration, rather than treating the grid resolution as temporal accuracy.</p></section>
<section class="panel"><h2>Taxonomy, scores and reproducibility</h2><p>Checkpoint <a href="https://huggingface.co/LiquidAI/d1-Omni-2B">LiquidAI/d1-Omni-2B</a>, revision <code>{esc(r['revision'])}</code>. Official <code>system_one</code>, <code>noul</code> and <code>choice multiple=True</code>. Default page settings are conservative binary groups of 16; the Fast grouped mode button selects the measured faster configuration.</p><p><a href="https://research.google.com/audioset/download_strong.html">AudioSet Strong</a>: 456 classes. <a href="https://research.google.com/audioset/download.html">Classic AudioSet</a>: 527. Hierarchy from <a href="https://github.com/audioset/ontology">Google AudioSet ontology</a>. IDs and names are preserved, sources hashed. Label lists: CC BY 4.0; ontology-derived metadata: CC BY-SA 4.0.</p><p>Raw means native, unsmoothed model scores, including the checkpoint’s own release calibration. No task-specific empirical calibration or pre-calibration logits are claimed. Causal EMA, hysteresis and event blocks are derived visualizations; missing intervals stay missing.</p><p><a href="./benchmark-result.json">Complete measured GPU results and real class scores (JSON)</a> · <a href="./browser-result.json">Browser integration results (JSON)</a> · <a href="./full-live-result.json">Full-class live results (JSON)</a> · <a href="./implementation.md">Implementation and restart manual</a></p></section>
<section class="panel"><h2>Verified functions</h2><ul>{''.join('<li>'+esc(x)+'</li>' for x in checks)}</ul><p>Six additional CPU contract tests cover taxonomy counts, invalid selections, partial windows, cache keys, missing-value semantics and causal impulse handling. Mobile layout checked at 390 px. Browser JavaScript errors: {len(browser['errors'])}.</p><h2>Deliberately absent</h2><p>No MIDI export, proximity/foreground/dominance scoring, learned temporal calibration or labeled AudioSet accuracy study. No synthesized model outputs. No private microphone recordings or credentials appear in these artifacts. Recordings are private to the browser capability, expire after about one hour and can be explicitly deleted.</p></section><footer><a href="./">← Back to the interactive lab</a><p>Report generated from saved test artifacts. Model timing, scene accuracy and temporal resolution are separate measurements.</p></footer></main></body></html>'''
if (ROOT/'static/batch64.html').exists():
    body=body.replace('<h2>The useful conclusion</h2>', '<h2>The useful conclusion</h2><p><strong>9 November update:</strong> <a href="./batch64.html">New experiment: batch unchanged 64-class groups together</a>. It measures additional speedups in an isolated prototype. The original deployed-path and live measurements remain below.</p>',1)
    body=body.replace('in the fastest tested stable configuration:', 'in the original deployed fast configuration:')
(ROOT/'static/report.html').write_text(body)
for source,name in [(ROOT/'benchmark-result.json','benchmark-result.json'),(ROOT/'tests/browser-result.json','browser-result.json'),(ROOT/'tests/full-live-result.json','full-live-result.json'),(ROOT/'README.md','implementation.md')]:
 if source.exists():shutil.copyfile(source,ROOT/'static'/name)
print('Report rebuilt from measured artifacts')
